<?php

$f = fopen("php://stdin", "r");
$line = fgets($f);
list($n, $m, $p) = explode(' ', trim($line));

$max = max($n, $m);
$fact = array_fill(0, $max + 1, 1);
for ($i = 1; $i <= $max; $i++) {
    $fact[$i] = ($fact[$i - 1] * $i) % $p;
}

$inv_fact = array_fill(0, $max + 1, 1);
$inv_fact[$max] = mod_pow($fact[$max], $p - 2, $p);
for ($i = $max; $i >= 1; $i--) {
    $inv_fact[$i - 1] = ($inv_fact[$i] * $i) % $p;
}

function C($n, $k, $fact, $inv_fact, $p) {
    if ($k < 0 || $k > $n) return 0;
    return (int)(($fact[$n] * $inv_fact[$k]) % $p * $inv_fact[$n - $k] % $p);
}

function mod_pow($a, $e, $p) {
    $res = 1;
    $a %= $p;
    while ($e > 0) {
        if ($e & 1) $res = ($res * $a) % $p;
        $a = ($a * $a) % $p;
        $e >>= 1;
    }
    return $res;
}

$A = array_fill(0, $n + 1, 0);
for ($L = 1; $L <= $n; $L++) {
    $A[$L] = mod_pow($L, $L - 1, $p);
}

$pow2 = array_fill(0, $n + 1, 1);
for ($i = 1; $i <= $n; $i++) {
    $pow2[$i] = ($pow2[$i - 1] * 2) % $p;
}

$fact_local = $fact;
$inv_fact_local = $inv_fact;
$p_local = $p;

$S = array_fill(0, $n + 1, array_fill(0, $m + 1, 0));
$S[0][0] = 1;
for ($j = 1; $j <= $m; $j++) $S[0][$j] = 0;

for ($i = 1; $i <= $n; $i++) {
    $S[$i][0] = 1;
    for ($j = 1; $j <= $m; $j++) {
        $sum = 0;
        for ($k = 1; $k <= min($i, $j); $k++) {
            $c = C($i - 1, $k - 1, $fact_local, $inv_fact_local, $p_local);
            $term = ($c * $A[$k]) % $p_local;
            $term = ($term * $pow2[$k - 1]) % $p_local;
            $term = ($term * $S[$i - $k][$j - $k]) % $p_local;
            $sum = ($sum + $term) % $p_local;
        }
        $S[$i][$j] = $sum;
    }
}

$dp1 = array_fill(0, $n + 1, array_fill(0, $m + 1, 0));
$dp2 = array_fill(0, $n + 1, array_fill(0, $m + 1, 0));
$dp1[0][0] = 1;

for ($i = 1; $i <= $n; $i++) {
    $dp1[$i][0] = 1;
    $dp2[$i][0] = 0;
    for ($j = 1; $j <= $m; $j++) {
        $ways = 0;
        $sum_val = 0;
        for ($k = 1; $k <= min($i, $j); $k++) {
            $c = C($i - 1, $k - 1, $fact_local, $inv_fact_local, $p_local);
            $a_k = $A[$k];
            $p2_k1 = $pow2[$k - 1];
            $base = ($c * $a_k) % $p_local;
            $base = ($base * $p2_k1) % $p_local;
            $ways_k = ($base * $S[$i - $k][$j - $k]) % $p_local;
            $ways = ($ways + $ways_k) % $p_local;

            // F(k) = k*(k-1) / 4 mod p
            $inv4 = mod_pow(4, $p_local - 2, $p_local);
            $F_k = ((int)($k * ($k - 1) % $p_local) * $inv4) % $p_local;

            $sum_mad_k = ($F_k * $p2_k1) % $p_local;
            $sum_mad_k = ($sum_mad_k * $S[$i - $k][$j - $k]) % $p_local;

            $dp2_rest = $dp2[$i - $k][$j - $k];
            $S_rest = $S[$i - $k][$j - $k];

            $total_mad = ($sum_mad_k + $dp2_rest) % $p_local;

            $sum_val = ($sum_val + $total_mad * $c % $p_local * $a_k % $p_local * $p2_k1) % $p_local;
        }
        $dp1[$i][$j] = $ways;
        $dp2[$i][$j] = $sum_val;
    }
}

echo $dp2[$n][$m] % $p;
